//! Symbols of the user interface as inline SVG: the shapes come from Lucide ([`super::lucide`], generated by
//! `dev/lucide-icons.py`), a few own shapes fill gaps (a network switch). Templates use [`icon`], or
//! [`shapes`] inside an `<svg>` of their own (e.g. with a title).

/// The SVG of the symbol `name` (a dot for an unknown name); `class` adds classes such as `lg`.
/// The result is markup: render it with `|safe` (it contains no user input).
pub fn icon(name: impl AsRef<str>, class: &str) -> String {
    let class: String = class
        .chars()
        .filter(|c| c.is_ascii_alphanumeric() || *c == '-' || *c == ' ')
        .collect();
    format!(
        "<svg class=\"icon {class}\" viewBox=\"0 0 24 24\" aria-hidden=\"true\">{}</svg>",
        shapes(name)
    )
}

/// The inner SVG markup (24 × 24, stroked) of the symbol `name`; a dot for an unknown name.
pub fn shapes(name: impl AsRef<str>) -> &'static str {
    let name = name.as_ref();
    super::lucide::shapes(name).unwrap_or(match name {
        // A network switch: a flat box with ports (in the style of Lucide's "router" and "server").
        "switch" => {
            r#"<rect width="20" height="8" x="2" y="8" rx="2"/><path d="M6 12h.01"/><path d="M10 12h.01"/><path d="M14 12h.01"/><path d="M18 12h.01"/>"#
        }
        _ => r#"<circle cx="12" cy="12" r="3"/>"#,
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn known_and_unknown_symbols() {
        assert!(icon("up", "lg").starts_with("<svg class=\"icon lg\""));
        assert!(icon("up", "").contains("<circle"));
        assert!(icon("switch", "").contains("<rect"));
        assert!(icon("nope", "").contains("r=\"3\""));
        assert!(!icon("up", "\"><script>").contains("<script"));
    }

    /// Every device kind has its own symbol (not the dot of an unknown name).
    #[test]
    fn every_device_kind_has_a_symbol() {
        let dot = shapes("nope");
        for kind in crate::devices::DeviceKind::ALL {
            assert_ne!(shapes(kind.as_str()), dot, "{}", kind.as_str());
        }
    }
}
